async def act(page):
    """
    - Attempt to use the knowledge-base helper create_curated_collection_by_search(...) to perform the visible-site search
      for 'Collector' (this helper navigates to '/'). If it returns a results list, attempt to click the first visible
      search-result (role='main' -> first role='article' -> first role='link'), then return the results list unchanged.
    - If the helper fails or returns None, fall back to a direct search URL '/?s=Collector', wait for role='main' and
      click the first article link. Return an empty list in the fallback case (no KB-API response to forward).

    Notes:
    - All .nth() indexing is guarded by .count() to avoid indexing errors.
    - The click that is expected to navigate away is performed as the last DOM-modifying action.
    """
    results = None

    # Helper attempt (use KB function if available)
    try:
        results = await create_curated_collection_by_search(page, "Collector")
    except Exception:
        results = None

    async def click_first_result_from_main():
        main = page.get_by_role("main")
        try:
            await main.wait_for(state="visible", timeout=3000)
        except Exception:
            # continue even if wait_for times out
            pass

        articles = main.get_by_role("article")
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

        if article_count > 0:
            first_article = articles.nth(0)
            links = first_article.get_by_role("link")
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0

            if link_count > 0:
                # Click the first link inside the first article (last DOM action expected)
                await links.nth(0).click()
                return True

            # Fallback: click the article itself if it's clickable
            try:
                await first_article.click()
                return True
            except Exception:
                return False

        # Final fallback: try first link under main
        main_links = main.get_by_role("link")
        try:
            main_link_count = await main_links.count()
        except Exception:
            main_link_count = 0

        if main_link_count > 0:
            await main_links.nth(0).click()
            return True

        return False

    # If the helper returned a list (API response), attempt to click the first visible result and return the API result as-is.
    if results is not None:
        try:
            await click_first_result_from_main()
        except Exception:
            # ignore click failures but still return the API result unchanged
            pass
        return results

    # Fallback: navigate directly to a search results URL and click the first result there.
    try:
        await page.goto('/?s=Collector')
    except Exception:
        # If navigation fails, continue with the current page
        pass

    # Wait for results area or network idle
    try:
        await page.get_by_role('main').wait_for(state='visible', timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state('networkidle')
        except Exception:
            pass

    # Click the first result (last DOM action)
    try:
        await click_first_result_from_main()
    except Exception:
        pass

    # No KB API response to pass back; return empty list.
    return []

